package example
import ("context";"errors";"testing")
func TestGeneratedCancelled(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());cancel()
    if !errors.Is(WaitForCancel(ctx),context.Canceled){t.Fatal("取消错误")}}

